import java.util.*;

class Solution {
  private final int[][] rects;
  private final long[] prefix;
  private final long total;
  private final Random random = new Random();

  public Solution(int[][] rects) {
    this.rects = rects;
    prefix = new long[rects.length];
    long sum = 0;
    for (int i = 0; i < rects.length; i++) {
      sum += (long) (rects[i][2] - rects[i][0] + 1) * (rects[i][3] - rects[i][1] + 1);
      prefix[i] = sum;
    }
    total = sum;
  }

  public int[] pick() {
    long target = (long) (random.nextDouble() * total) + 1;
    int lo = 0, hi = prefix.length - 1;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (prefix[mid] < target) lo = mid + 1;
      else hi = mid;
    }
    int[] r = rects[lo];
    int width = r[2] - r[0] + 1;
    long before = lo == 0 ? 0 : prefix[lo - 1];
    long offset = target - before - 1;
    return new int[] {r[0] + (int) (offset % width), r[1] + (int) (offset / width)};
  }
}
